<script setup lang="ts">import { computed } from 'vue'; import type { CodeItem } from '../api/contracts'; const props=defineProps<{ modelValue: string | null; items: CodeItem[]; category: string; id: string; emptyLabel?: string; disabled?: boolean; required?: boolean; search?: boolean }>(); defineEmits<{ 'update:modelValue': [value: string | null] }>(); const options=computed(()=>props.items.filter(i=>i.categoryId===props.category));</script>
<template><select :id="id" :value="modelValue || ''" :disabled="disabled" :required="required" @change="$emit('update:modelValue',($event.target as HTMLSelectElement).value || null)"><option value="">{{ emptyLabel || '未選択' }}</option><option v-for="item in options" :key="item.value" :value="item.value" :disabled="!search && !item.selectable && item.value!==modelValue">{{ item.name }}{{ !item.selectable ? '（停止・期間外）' : '' }}</option></select></template>
